    source: "ANSA",
    url: "https://www.ansa.it/canale_tecnologia/notizie/software_app/2026/10/22/anthropic-sfida-meta-e-lancia-lassistente-claude-duet-per-il-lavoro-quotidiano_6386da1e-771b-4bdb-bee0-1e3922444647.html",
    time: "17 ore fa",
